FROM bt_job
WHERE state = '00A'
AND bss_job_name = #{dto.bssJobName}
AND tenant_id = #{dto.tenantId}

  AND space_id = #{dto.spaceId}


  AND bot_id = #{dto.botId}


  AND creator_id = #{dto.creatorId}


  AND bss_job_id != #{dto.bssJobId}

