FROM bt_job a WHERE 1=1
AND a.state = #{query.state}

SELECT , a.bss_job_name as jobName FROM bt_job_log b LEFT JOIN bt_job a ON b.job_id = a.bss_job_id WHERE 1=1 AND a.tenant_id = #{query.tenantId}
AND a.bss_job_name LIKE
#{query.searchContent}
